import{af as e,z as t,J as s,ab as i}from"./chunks/framework.BnTFvF69.js";const m=JSON.parse('{"title":"BLE Scans","description":"","frontmatter":{},"headers":[],"relativePath":"apps/chasm/share/ble-scan.md","filePath":"apps/chasm/share/ble-scan.md"}'),n={name:"apps/chasm/share/ble-scan.md"};function r(o,a,c,d,h,p){return t(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793203908000"},[...a[0]||(a[0]=[i('<h1 id="ble-scans" tabindex="-1">BLE Scans <a class="header-anchor" href="#ble-scans" aria-label="Permalink to &quot;BLE Scans&quot;">​</a></h1><p>When BLE scan data is included in a share, it is shown in the BLE Scans section of the share page.</p><h2 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h2><p>Positions of scans are inferred from the position of the device at the time of the scan, and are shown on a map when location data is included in the share.</p><p>There are various filters that can be applied to reduce noise and find the data that is relevant to you, such as filtering by RSSI, or by device name.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/03/chrome_2vEit3u44G.jpg" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="over-time" tabindex="-1">Over time <a class="header-anchor" href="#over-time" aria-label="Permalink to &quot;Over time&quot;">​</a></h2><p>Some summary graphs are also included showing the number of scans over time, and the distribution of RSSI values.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/03/chrome_2a0TlnN5AG.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="scan-data" tabindex="-1">Scan data <a class="header-anchor" href="#scan-data" aria-label="Permalink to &quot;Scan data&quot;">​</a></h2><p>Finally the scan data is displayed in a table at a per MAC address level.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2026/03/chrome_WvyZADmjEf.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>If you wish to see the raw scan data, you can download the messages at the top of the page, and process them to see the raw data.</p>',13)])])}const f=e(n,[["render",r]]);export{m as __pageData,f as default};
